void process_init( void ) 
{
    static Boolean do_one_time = FALSE ; 

    if( !do_one_time )
    {    
        process_q_init( &process_exec_list    );
        process_q_init( &process_suspend_list );

        per_exec_register( (Per_Exec_Func)process_looping_exec );

        do_one_time = TRUE ;
    }
}

